import sys
from collections import defaultdict

def countSubstring(S: str) -> int:
    balance = 0
    prefix_counts = defaultdict(int)
    prefix_counts[0] = 1
    total_substrings = 0

    for char in S:
        if char == '1':
            balance += 1
        else:
            balance -= 1

        if balance > 0:
            total_substrings += prefix_counts[0]

        needed = balance - 1
        if needed >= 0:
            total_substrings += prefix_counts.get(needed, 0)

        prefix_counts[balance] += 1

    return total_substrings

if __name__ == "__main__":
    S = sys.stdin.read().strip()
    if S:
        result = countSubstring(S)
        print(result)
